(function(){function place(){document.querySelectorAll('.es-actions-more[open]').forEach(m=>{const p=m.querySelector('.es-overflow-menu');if(!p)return;const r=m.querySelector('summary').getBoundingClientRect(),width=Math.min(220,innerWidth-24);p.style.width=width+'px';p.style.left=Math.max(12,Math.min(r.right-width,innerWidth-width-12))+'px';const up=innerHeight-r.bottom<200 && r.top>innerHeight-r.bottom;p.style.maxHeight=Math.max(60,Math.min(320,up?r.top-24:innerHeight-r.bottom-24))+'px';p.style.top=(up?Math.max(12,r.top-p.getBoundingClientRect().height-6):r.bottom+6)+'px';});}document.addEventListener('toggle',e=>{if(e.target.matches('.es-actions-more'))place();},true);document.addEventListener('click',e=>{document.querySelectorAll('.es-actions-more[open]').forEach(m=>{if(!m.contains(e.target))m.open=false;});});document.addEventListener('keydown',e=>{const menus=document.querySelectorAll('.es-actions-more[open]');if(e.key==='Escape'&&menus.length){e.preventDefault();e.stopImmediatePropagation();menus.forEach(m=>m.open=false);}},true);window.addEventListener('resize',place);window.addEventListener('scroll',place,true);})();

